const happinessStops=[{value:0,color:'#800020',label:'Very unhappy'},{value:25,color:'#df5446',label:'Unhappy'},{value:50,color:'#f5f3ed',label:'Neutral'},{value:75,color:'#83caff',label:'Happy'},{value:100,color:'#0084ff',label:'Very happy'}];
function happinessColor(value){const n=Math.max(0,Math.min(100,value));const i=Math.min(3,Math.floor(n/25)),a=happinessStops[i],b=happinessStops[i+1],mix=(n-a.value)/(b.value-a.value);const rgb=hex=>[1,3,5].map(j=>parseInt(hex.slice(j,j+2),16));return 'rgb('+rgb(a.color).map((v,j)=>Math.round(v+(rgb(b.color)[j]-v)*mix)).join(',')+')';}
function happinessLegend(){return `<div class="happiness-key"><strong>Happiness heat map</strong><div class="happiness-gradient" aria-hidden="true" style="background:linear-gradient(to right,${happinessStops.map(s=>s.color+' '+s.value+'%').join(',')})"></div><div class="happiness-labels">${happinessStops.map(s=>`<span><b>${s.value}</b><br>${s.label}</span>`).join('')}</div><p>0 = 50% production · 50 = 100% · 100 = 150%. Select a territory for its exact happiness. Water is gray.</p></div>`;}
