$('cancel').onclick=()=>$('confirm').close();$('confirmYes').onclick=()=>{$('confirm').close();const fn=pending;pending=null;fn?.();};
try{const raw=localStorage.getItem(KEY);state=raw?DepartmentBudget.init(R.validate(JSON.parse(raw))):fresh();}catch{unreadableSave=localStorage.getItem(KEY);state=fresh();$('recover').hidden=false;notice('Could not open the saved regiment game. Autosave is paused. Download the unreadable save, then open a backup or start a new world.');}
