  living().filter(u=>u.country===active).forEach(u=>{const resting=u.supportTurn===state.turn;const destinations=state.territories.filter(t=>{const p=R.route(state,u.territory,t.id,u.country);return p&&p.length<=c.movement;});const box=document.createElement('article');box.className='regiment';box.innerHTML=`<div class="regiment-heading">${troopPicture(u.type)}<h3>${R.types[u.type].name} #${u.id} · ${u.hp}/100 health · ${R.development.gearNames[u.type][u.gear]}${u.readyTurn>state.turn?' · TRAINING until round '+u.readyTurn:''}</h3></div><div class="health"><span style="width:${u.hp}%"></span></div><p>Territory ${u.territory+1}${u.retreat?.turn===state.turn?' · <strong class="retreat">Retreated: moving away risks pursuit damage this turn</strong>':''}</p><div class="row"><label>Destination <select class="destination" ${u.readyTurn>state.turn||resting?'disabled':''}>${options(destinations.map(t=>[t.id,`${t.id+1} · ${t.name} (${R.route(state,u.territory,t.id,u.country).length} moves)`]),u.order?.destination??u.territory)}</select></label><label>Plan <select class="intent" ${u.readyTurn>state.turn||resting?'disabled':''}><option value="move">Move / hold</option><option value="capture">Capture land</option></select></label><button ${u.readyTurn>state.turn||resting?'disabled':''}>Save order</button></div><p>${u.order?`Saved: ${u.order.intent} at territory ${(u.order.destination??u.territory)+1}`:'No order: holds position.'}</p><button type="button" class="find-regiment">Find on map</button>`;box.querySelector('.find-regiment').onclick=()=>focusTerritory(u.territory);box.querySelector('.intent').value=u.order?.intent||'move';box.querySelector('button').onclick=()=>change(s=>R.order(s,u.id,Number(box.querySelector('.destination').value),box.querySelector('.intent').value),'Order saved. It will resolve with everyone else.');const equip=document.createElement('button');equip.textContent='Re-equip to '+R.development.gearNames[u.type][R.development.gear(c,u.type)]+' · '+R.goods.filter(g=>R.development.equipCost(c,u)[g]).map(g=>R.development.equipCost(c,u)[g]+' '+g).join(', ')+' (rest this round)';equip.disabled=R.development.gear(c,u.type)<=u.gear||resting;equip.onclick=()=>change(s=>R.development.equip(s,active,u.id),'Regiment re-equipped and resting this round.');box.append(equip);if(resting)box.append(Object.assign(document.createElement('p'),{textContent:'Resting for city support or equipment upgrade; cannot move this round.'}));panel.append(box);});
  if(!living().some(u=>u.country===active))panel.append(Object.assign(document.createElement('p'),{textContent:'No living regiments. Recruit in controlled territory. If you have lost all land, the teacher can start a new campaign or restore a previous phase.'}));
