$('country').onchange=e=>{active=Number(e.target.value);selected=state.countries[active].capital??0;render();};$('territory').onchange=e=>{selected=Number(e.target.value);popupOpen=$('layer').value!=='resources';render();};$('layer').onchange=()=>{popupOpen=false;render();};$('resourceFilter').onchange=draw;
