$('save').onclick=()=>download(new Blob([JSON.stringify(state)],{type:'application/json'}),`regiment-game-turn-${state.turn}.json`);$('mapDownload').onclick=()=>{const copy=document.createElement('canvas');copy.width=1200;copy.height=700;const exportCtx=copy.getContext('2d');exportCtx.drawImage($('map'),0,0);if($('layer').value==='resources')resourceMap.paintExport(exportCtx);copy.toBlob(blob=>download(blob,`turn-${state.turn}-${state.phase}.png`));};
$('advance').onclick=()=>ask('Advance all countries together? Unissued movement orders hold. Missing conflict choices or retreats will stop the advance.',()=>{try{const next=DepartmentBudget.record(state,R.advance(state));localStorage.setItem(KEY+'-previous',JSON.stringify(state));state=next;save();render();notice('Phase resolved. Review the map and results.');}catch(e){notice(e.message);}});
$('undo').onclick=()=>ask('Restore the previous phase? Download the current game first if you want to keep it.',()=>{try{const raw=localStorage.getItem(KEY+'-previous');if(!raw)throw Error('No previous phase checkpoint yet.');const previous=DepartmentBudget.init(R.validate(JSON.parse(raw)));localStorage.setItem(KEY+'-previous',JSON.stringify(state));state=previous;active=0;selected=0;save();render();notice('Previous phase restored.');}catch(e){notice(e.message);}});
