async function load(e,importing){const file=e.target.files[0];if(!file)return;try{if(file.size>35e6)throw Error('Choose a file smaller than 35 MB.');const raw=JSON.parse(await file.text()),next=DepartmentBudget.init(R.validate(importing?R.create(importAzgaarWorld(raw)):raw),importing);ask('Replace the current regiment game? A previous-phase checkpoint will be kept.',()=>{try{localStorage.setItem(KEY+'-previous',JSON.stringify(state));state=next;unreadableSave=null;$('recover').hidden=true;active=0;selected=0;save();render();notice('Game opened.');}catch(error){notice(error.message);}});}catch(error){notice(error.message);}e.target.value='';}
